"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5383],{9596(e){e.exports=JSON.parse('{"title":"\ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 \uacfc\uac70\uc640 \ud604\uc7ac","date":"2024-03-26","coverUrl":null,"html":"<h2 data-notion-block-id=\\"44319358-d78c-4227-950b-e11083ea5513\\" id=\\"44319358-d78c-4227-950b-e11083ea5513\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 \uacfc\uac70\uc640 \ud604\uc7ac</h2><a href=\\"https://frontendmastery.com/posts/navigating-the-future-of-frontend/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmastery.com/posts/navigating-the-future-of-frontend/</a><p data-notion-block-id=\\"48ea3e9f-9d2c-4754-ac69-4263d018a46c\\"><b>\uc2ec\uc724\uc12d</b>: \ud504\ub860\ud2b8\uc5d4\ub4dc\uac00 \ud604\uc7ac \uac77\uace0 \uc788\ub294 \uae38\uc744 \ubaa8\ub450 \uc815\ub9ac\ud574\ub1a8\ub2e4\uace0 \ud574\ub3c4 \uacfc\uc5b8\uc774 \uc544\ub2d0\uc815\ub3c4\ub85c \ub9e4\uc6b0 \ub9ce\uc740 \uc815\ubcf4\uac00 \ub4e4\uc5b4\uac04 \uae00\uc785\ub2c8\ub2e4. SPA\ub97c \ud1b5\ud574 \uac1c\ucc99\ub41c \ud504\ub860\ud2b8\uc5d4\ub4dc \ubd84\uc57c\uac00 \ub2e4\uc2dc \uc11c\ubc84\uac00 \ub9ce\uc774 \ud544\uc694\ud574\uc9c0\uba74\uc11c \ub2e4\uc591\ud55c \uae30\uc220\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4. \ub2e4\uc591\ud55c \uae30\uc220\uc774 \uc3df\uc544\uc9c8 \ub54c \uc6b0\ub9ac\uac00 \ud574\uc57c \ud560 \uac83\uc740 \uae30\ubcf8\uc73c\ub85c \ub3cc\uc544\uac00 \uc6b0\ub9ac\uc5d0\uac8c \ud544\uc694\ud55c \uae30\uc220(\ub3c4\uad6c)\ub9cc\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc785\ub2c8\ub2e4(\ubb3c\ub860 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0 \ubc1c\uc744 \ub4e4\uc5ec\ub193\uc740\uc9c0 \uc624\ub798\ub418\uc9c0 \uc54a\uc558\ub2e4\uba74 \ud798\ub4e4\uaca0\uc9c0\ub9cc\uc694). \uadf8\ub798\uc11c \uc774 \uae00\uc740 \uc624\ub7ab\ub3d9\uc548 \ubd84\uc11d\ud558\uba74\uc11c \ubcf4\uc168\uc73c\uba74 \ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"7f96b29e-fca6-45c4-a3ef-db25fef8a179\\"><b>\uae40\ub300\uad00</b>: \ud504\ub860\ud2b8\uc5d4\ub4dc\uac00 \uacfc\uac70 \uae30\uc220\uc5d0\uc11c \ubc1c\uc804\uc774 \uc774\ub8e8\uc5b4\uc9c0\uba74\uc11c \ud604\uc7ac\uc758 \uc0c1\ud669\uae4c\uc9c0\ub97c \uc2dc\uac04\uc758 \ud750\ub984\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub294 \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4. \ud574\ub2f9 \uae00\uc744 \ud1b5\ud574 \uc6f9 \uae30\uc220\uc758 \ud788\uc2a4\ud1a0\ub9ac\ub97c \uc774\ud574\ud558\uba74\uc11c \uc55e\uc73c\ub85c \ud504\ub860\ud2b8\uc5d4\ub4dc \uae30\uc220\uc758 \ubc1c\uc804\uc774 \uc5b4\ub5bb\uac8c \ub420 \uac83\uc778\uc9c0 \ubcf8\uc778 \uc2a4\uc2a4\ub85c \uc778\uc9c0\ud558\uace0 \uae30\uc220\ubcc0\ud654\ub97c \ub300\ube44\ud558\ub294 \ub9c8\uc778\ub4dc\uc14b\uc774 \ud544\uc694\ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"58222d4b-9379-4eb1-b56e-29a2cd6356b5\\" id=\\"58222d4b-9379-4eb1-b56e-29a2cd6356b5\\">INP\uac00 \ubb54\ub370?</h2><a href=\\"https://blog.sentry.io/what-is-inp/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.sentry.io/what-is-inp/</a><p data-notion-block-id=\\"f0f1930a-79cb-441f-87cc-0584159a4076\\"><b>\uc2ec\uc724\uc12d</b>: 2024.03.12\uc5d0 Core Web Vital\uc5d0 FID \ub300\uc2e0 INP\uac00 \ub4e4\uc5b4\uc654\uc2b5\ub2c8\ub2e4. Sentry\uce21\uc5d0\uc11c \uc0ac\uc774\ud2b8 \uc131\ub2a5 \ucd5c\uc801\ud654\uc640 \uad6c\uae00\uc758 \uac80\uc0c9 \uc21c\uc704\ub97c \uc704\ud574 INP\ub97c \uc18c\uac1c\ud558\ub294 \ub0b4\uc6a9\uc785\ub2c8\ub2e4. INP\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c \uc0c8\ub85c\uc6b4 \ubc29\ubc95(<code>isInputPending</code>, <code>yield</code>, \uc0c8\ub85c\uc6b4 \uc2a4\ucf00\uc904\ub7ec)\uc744 \uc18c\uac1c\ud558\uc9c0\ub9cc..\uc544\uc9c1\uc740 debounce\uc640 throttle\uc744 \uc801\uc6a9\ud574\uc57c \ud560 \uac83 \uac19\ub124\uc694.</p><p data-notion-block-id=\\"789f0ac7-7282-4cce-8e65-01fe6a126546\\"><b>\uae40\ub300\uad00</b>: \uad6c\uae00 \uac80\uc0c9 \uc21c\uc704\uc5d0 \ub300\ud55c \uae30\uc900\uc774 FID\uc5d0\uc11c INP\ub85c \ubcc0\uacbd\ub41c \uc774\uc720\ub294 chrome\uc5d0\uc11c \uc720\uc800\uc758 \ud589\ub3d9\uc744 \ubd84\uc11d\ud558\ub294 90%\uac00 \uc6f9 \ub0b4\ubd80\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \ud589\ub3d9\uc774\uae30\uc5d0 \uc774\ub7ec\ud55c \ucc99\ub3c4\ub97c \ubcc0\uacbd\ud55c \uac83\uc785\ub2c8\ub2e4. \ud55c\ub9c8\ub514\ub85c \uacfc\uac70 \uc6f9\ud398\uc774\uc9c0\uac00 \ucd08\uae30 \ub85c\ub529\uc774 \uac00\uc7a5 \uc911\uc694\ud588\ub2e4\uba74, \uc774\uc81c\ub294 \ud398\uc774\uc9c0 \uae30\ub2a5\uc758 \ube44\ub3d9\uae30 \uacfc\uc815\uc744 \ucc98\ub9ac\ub97c \ud1b5\ud574 \uc0ac\uc6a9\uc790\uc5d0\uac8c \ubcf4\uc5ec\uc9c0\ub294 \uc815\ub3c4\ub97c \ub354 \uc911\uc694\ud558\uac8c \ubcf4\uaca0\ub2e4\ub294 \uc758\ubbf8\ub85c \ub290\uaef4\uc9d1\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d215dff3-0b22-4545-9c01-d944a4809548\\" id=\\"d215dff3-0b22-4545-9c01-d944a4809548\\">NextJS\uc758 \uc11c\ub4dc\ud30c\ud2f0 \uc2a4\ud06c\ub9bd\ud2b8\ub97c \uc704\ud55c \ub178\ub825</h2><a href=\\"https://developer.chrome.com/blog/next-third-parties?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/next-third-parties?hl=ko</a><p data-notion-block-id=\\"e279548c-697a-4c60-93d9-2fed9a5cbea5\\"><b>\uc2ec\uc724\uc12d</b>: NextJS\uc758 <code>Script</code> \ud0dc\uadf8\ub97c \ub354 \uc27d\uac8c \uad00\ub9ac\ud558\ub3c4\ub85d <code>@next/third-parties</code>\ud328\ud0a4\uc9c0\ub97c \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. NextJS\uc5d0\uc11c\ub294 <code>Script</code> \ud0dc\uadf8\uc758 <code>strategy</code>\uac12\uc744 \ud1b5\ud574 \ud658\uacbd\uc5d0 \ub9de\ub294 \uc804\ub7b5\uc744 \uad6c\uc0ac\ud558\uace0 \uc788\uace0, \uc774\ub97c \ub354 \uc27d\uac8c \uc0ac\uc6a9\ud558\ub3c4\ub85d <code>@next/third-parties</code>\ud328\ud0a4\uc9c0\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ud558\ub124\uc694. \uc774\uc678\uc5d0\ub3c4 <a href=\\"https://github.com/BuilderIO/partytown\\">Worker\uc5d0\uc11c \ubd88\ub7ec\uc624\ub294 \ubc29\uc2dd</a>\ub3c4 \uc788\uc73c\ub2c8 \ucc38\uace0\ud558\uc138\uc694. :)</p><h2 data-notion-block-id=\\"29fb3d8c-b9dc-4c5f-b069-f23ff068692a\\" id=\\"29fb3d8c-b9dc-4c5f-b069-f23ff068692a\\">\uba85\ud655\ud55c \ud14c\uc2a4\ud2b8\ub97c \uc704\ud55c \uc554\uc2dc\uc801 Assert</h2><a href=\\"https://www.epicweb.dev/implicit-assertions\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicweb.dev/implicit-assertions</a><p data-notion-block-id=\\"25beecd3-451a-45d2-9f71-9a3c96c9216e\\"><b>\uc2ec\uc724\uc12d</b>: \ud14c\uc2a4\ud2b8\ub97c \uc9c4\ud589\ud560 \ub54c \ud14c\uc2a4\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ud568\uc218\ub97c \uc0ac\uc6a9\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774 \ub54c \ud14c\uc2a4\ud2b8 \ucf54\ub4dc\ub97c \uc9e4 \ub54c \ud14c\uc2a4\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ud568\uc218\ub294 \uc5ec\ub7ec\uac00\uc9c0 \uc554\uc2dc\uc801 assertion\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4\ub294 \uac83\uc744 \uc778\uc9c0\ud558\uace0 \ud544\uc694 \uc5c6\ub294 \ud14c\uc2a4\ud2b8 \ucf54\ub4dc\ub97c \uc0ad\uc81c\ud574\uc57c \ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud569\ub2c8\ub2e4. \uac1c\uc778\uc801\uc73c\ub85c \ub354 \ub098\uc544\uac00\uc11c \ud14c\uc2a4\ud2b8 \ucf54\ub4dc\uac00 \ubb38\uc11c\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub3c4\ub85d \ud558\ub294\uac8c \ucd5c\uc120\uc77c \uc218\ub3c4 \uc788\ub2e4\ub294 \uc0dd\uac01\uc785\ub2c8\ub2e4. \ud14c\uc2a4\ud2b8 \ucf54\ub4dc\ub97c \ud604\uc7ac \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc544\ub3c4 \ubcfc\ub9cc\ud55c \uae00\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2c964c01-95ca-4ec2-a409-d151ee87b9ea\\" id=\\"2c964c01-95ca-4ec2-a409-d151ee87b9ea\\">React \ucef4\ud30c\uc77c\ub7ec\uc758 \ud0c0\uc785 \uc2dc\uc2a4\ud15c</h2><a href=\\"https://www.recompiled.dev/blog/type-system/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.recompiled.dev/blog/type-system/</a><p data-notion-block-id=\\"a70bc1b6-dbb8-4673-ba13-a60968b3dba4\\"><b>\uc2ec\uc724\uc12d</b>: React \ucef4\ud30c\uc77c\ub7ec\uc5d0\uc11c \ud0c0\uc785 \ucd94\ub860\uc744 \uc704\ud574 \uc0ac\uc6a9\ud558\ub294 \uc2dc\uc2a4\ud15c\uc744 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. JavaScript \ucf54\ub4dc\ub9cc\uc73c\ub85c \ucd94\ub860\ud558\ub294 \ubc29\uc2dd\uc744 \ubcf4\uc5ec\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ucd94\ub860\uc5d0 \ub300\ud55c \uc2dc\uc2a4\ud15c\uc774\ub098 \ub17c\ubb38\uc744 \uc18c\uac1c\ud574 \uc5b4\ub824\uc6b4 \uae00\uc774\uc9c0\ub9cc, \ud0a4\uc6cc\ub4dc\ub9cc \uac00\ubccd\uac8c \ubcf4\uace0 \ub118\uc5b4\uac08\ub9cc\ud55c \uae00\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"45c2bf64-b1f6-49b0-b4b4-f3b88069a713\\" id=\\"45c2bf64-b1f6-49b0-b4b4-f3b88069a713\\">TS 5.5\uc758 \ud0c0\uc785 \uc220\uc5b4(<code>A is Type</code>)\ucd94\ub860 \uae30\ub2a5</h2><a href=\\"https://www.totaltypescript.com/type-predicate-inference\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/type-predicate-inference</a><p data-notion-block-id=\\"7bf0d063-b663-4d3a-8378-32932a025c0d\\">\ub354 \uc88b\uc740 TypeScript\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 <a href=\\"https://github.com/total-typescript/ts-reset\\">ts-reset</a>\uacfc \ud568\uaed8 TypeScript 5.5\uc5d0 \ucd94\uac00\ub420 \ud0c0\uc785 \uc220\uc5b4 \ucd94\ub860 \uae30\ub2a5\uc5d0 \ub300\ud574 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"e89490d5-b565-4944-a1fc-94c518cc9da0\\" id=\\"e89490d5-b565-4944-a1fc-94c518cc9da0\\">React \ub80c\ub354\ub9c1 \ub300\ud654\ud615 \uac00\uc774\ub4dc</h2><a href=\\"https://ui.dev/why-react-renders\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ui.dev/why-react-renders</a><p data-notion-block-id=\\"2bbd8f36-2c9b-4c68-9997-390f73be83c6\\"><b>\uc2ec\uc724\uc12d</b>: React \ub80c\ub354\ub9c1\uc774 \uc5b4\ub5bb\uac8c \ub418\ub294\uc9c0\uc5d0 \ub300\ud55c \uc774\ud574\ud558\uae30 \uc26c\uc6b4 \ub300\ud654\ud615 \uac00\uc774\ub4dc\uc785\ub2c8\ub2e4. \uc2ec\ud654\ub85c \uac00\uace0 \uc2f6\uc73c\uc2dc\ub2e4\uba74 <a href=\\"https://blog.isquaredsoftware.com/2020/05/blogged-answers-a-mostly-complete-guide-to-react-rendering-behavior/\\">\ud56d\uc0c1 \ub098\uc624\ub294 \uc774 \uae00</a>\uc744 \uc77d\uc5b4\uc8fc\uc138\uc694 \ud83d\ude42</p><h2 data-notion-block-id=\\"7c2b3c62-c9dc-4f18-a75c-896dd60099f5\\" id=\\"7c2b3c62-c9dc-4f18-a75c-896dd60099f5\\">DMAIC \uc811\uadfc\ubc95 \uc18c\uac1c</h2><a href=\\"https://www.callstack.com/blog/consistently-improve-app-performance-with-dmaic-and-reassure\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/consistently-improve-app-performance-with-dmaic-and-reassure</a><p data-notion-block-id=\\"2ecf7e9a-8d8d-474c-93ea-2a9ecd4d9324\\"><b>\uc2ec\uc724\uc12d</b>: \ub9ac\uc561\ud2b8 \ub124\ube44\uac8c\uc774\uc158 \uc131\ub2a5 \ucd5c\uc801\ud654 \uacfc\uc815\uc744 \ud1b5\ud574 DMAIC \uc811\uadfc\ubc95\uc744 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc131\ub2a5\uc5d0 \ub300\ud55c \ud504\ub85c\uc138\uc2a4\ub97c \uc138\uc6b0\uace0 \uc2f6\uc744 \ub54c \uace0\ub824\ud574\ubcf4\uba74 \uc88b\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc \uc774\ub7f0 \uc2dc\uc2a4\ud15c\uc744 \uad6c\ucd95\ud558\ub294 \uac83\ub3c4 \uc2dc\uac04\uc774 \ub9ce\uc774 \ub4e4\uae30 \ub54c\ubb38\uc5d0 \ube60\ub974\uac8c \uace0\uccd0\uc57c \ud560 \uacbd\uc6b0\ub77c\uba74 \uc801\ub2f9\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"27764d27-2941-4638-9162-fbab64031d9c\\" id=\\"27764d27-2941-4638-9162-fbab64031d9c\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://wasmer.io/posts/winterjs-v1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://wasmer.io/posts/winterjs-v1</a><a href=\\"https://github.com/mui/material-ui/tree/master/packages/pigment-css-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/mui/material-ui/tree/master/packages/pigment-css-react</a><a href=\\"https://storybook.js.org/blog/storybook-8/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://storybook.js.org/blog/storybook-8/</a><p data-notion-block-id=\\"3d6309ab-f4be-4d29-949a-d2d151f8d6ab\\"><b>\uc2ec\uc724\uc12d</b>: \ub9ce\uc544\uc11c \uc8fc\ubaa9\ud560 \ub9cc\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud55c\uaebc\ubc88\uc5d0 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uccab\ubc88\uc9f8\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/5c2a8faf-fd60-46cd-9bd2-d18b226e996f\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 LLRT</a>\uc640 \ube44\uc2b7\ud55c \ub7f0\ud0c0\uc784\uc778 WinterJS\uc785\ub2c8\ub2e4. \ub9e4\uc6b0 \ube60\ub974\uace0 \uae30\uc874 \uc6f9 \ud504\ub808\uc784\uc6cc\ud06c + WinterCG + Cloudflare API\uc640 \ud638\ud658, Bun\ubcf4\ub2e4 \ube60\ub978 \uc18d\ub3c4\ub97c \uac16\uace0 \uc788\ub294 \ub7f0\ud0c0\uc784\uc785\ub2c8\ub2e4. \uc544\uc9c1\uc740 Bun\ucc98\ub7fc \ub3c4\uc785\ud558\uae30\uc5d0 \uc5b4\ub835\uc9c0\ub9cc \uc9c0\ucf1c\ubcfc\ub9cc \ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ub450\ubc88\uc9f8\ub294 MUI\ud300\uc5d0\uc11c emotion\uc744 \uacc4\uc2b9\ud558\ub294 zero \ub7f0\ud0c0\uc784 CSS-in-JS\uc785\ub2c8\ub2e4. CSS-in-JS\uc640 utility-first CSS\ub97c \ud480\uc5b4\ub0b4\ub294 \ubc29\uc2dd\uc744 \uc9c0\ucf1c\ubcf4\uace0 \ud300\uc5d0\uac8c \ub9de\ub294 \uae30\uc220\uc744 \uc120\ud0dd\ud558\ub294\uac8c \uc911\uc694\ud558\uaca0\ub124\uc694(CSS \uae30\uc220\uc774 \ub354 \ud30c\ud3b8\ud654\ub420 \uac83\uc73c\ub85c \ubcf4\uc5ec\uc11c\uc694!). \uc138\ubc88\uc9f8\ub294 UX \uac1c\uc120, \uc131\ub2a5 \uac1c\uc120, \uc5ec\ub7ec \uae30\uc220\uacfc \ud1b5\ud569\uc744 \ucd94\uac00\ud55c \uc2a4\ud1a0\ub9ac\ubd81 8 \ucd9c\uc2dc \uae00\uc785\ub2c8\ub2e4. \ud14c\uc2a4\ud2b8\ub97c \uc2dc\uc791\ud560 \ub54c \uc2a4\ud1a0\ub9ac\ubd81\uc774 Jest\ucc98\ub7fc \uaf2d \ud544\uc694\ud55c \ud328\ud0a4\uc9c0\uac00 \ub420 \uc218\ub3c4 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"bcd8718b-a6c3-4398-b299-0e9eac9b0717\\" id=\\"bcd8718b-a6c3-4398-b299-0e9eac9b0717\\">\ud504\ub808\uc784\uc6cc\ud06c \uae30\ubcf8 \ubc30\uc6b0\uae30</h2><a href=\\"https://unicorn-utterances.com/collections/framework-field-guide\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://unicorn-utterances.com/collections/framework-field-guide</a><p data-notion-block-id=\\"f373144e-afbd-4f6a-a4e5-3641104a7e72\\">\uc138\uac1c\uc758 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uae30\ubcf8\uc740 \ubaa8\ub450 \uac19\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4(\uadf8 \uc678\ub3c4\uc694). \uadf8 \uae30\ubcf8\uc744 \uc27d\uac8c \ubc30\uc6b8 \uc218 \uc788\ub294 \ucc45\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"db5d56d7-67ae-46a3-b3bd-90b72eedf294\\" id=\\"db5d56d7-67ae-46a3-b3bd-90b72eedf294\\">Million Lint</h2><a href=\\"https://million.dev/blog/lint\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://million.dev/blog/lint</a><p data-notion-block-id=\\"7f9876c2-ba7c-4820-a8e9-42423768a44e\\">\ub9ac\uc561\ud2b8\uc758 \uc131\ub2a5 \uac1c\uc120\uc744 \ubc18\uc790\ub3d9\uc73c\ub85c \ud0d0\uc9c0\ud574 \uc8fc\ub294 \ud234\uc774\ub77c\uace0 \ud558\ub124\uc694. \uc720\ub8cc\ub85c \ud560\uac83\uc774\ub77c\ub294 \uc18c\uc2dd\uc774\uc9c0\ub9cc \uc2e0\uae30\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4 \ud83d\ude05</p><p data-notion-block-id=\\"863d8678-b86f-4f5c-bcb5-e60d98b8dee1\\"></p>"}')}}]);